mapper.select:
SELECT item_name AS item, pct, votes, response_count AS respondents
FROM fact_ce_ranking_scores
WHERE ce_database_id = (SELECT id FROM param_ce_database_registry WHERE is_active ORDER BY is_default DESC, id LIMIT 1)
  AND theme = 'community_facilities_needs' AND sub_category = ''
  AND calc_version_id = #{version}
  AND district_id = #{livDistrictId}
  AND response_count >= #{minRespondents}
ORDER BY pct DESC, item_name
LIMIT #{limit}
